{
  "title": "Weekend Trip Planner",
  "body": "<div class='wrap'>
  <h2>Weekend trip planner</h2>
  <div class='add-row'>
    <input id='new-todo' type='text' placeholder='Add a thing to do...' />
    <button id='add-btn'>Add</button>
  </div>
  <ul id='todo-list'></ul>
  <p id='counter'></p>
</div>",
  "css": ".wrap { font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif; max-width: 420px; margin: 0 auto; padding: 18px; color: #1f2933; }
h2 { font-size: 20px; margin: 0 0 12px; }
.add-row { display: flex; gap: 8px; margin-bottom: 12px; }
#new-todo { flex: 1; padding: 8px 10px; font-size: 14px; border: 1px solid #cbd2d9; border-radius: 8px; }
#add-btn { padding: 8px 14px; font-size: 14px; border: none; border-radius: 8px; background: #2563eb; color: white; cursor: pointer; }
#add-btn:hover { background: #1d4ed8; }
#todo-list { list-style: none; margin: 0 0 10px; padding: 0; }
.todo-item { display: flex; align-items: center; gap: 8px; padding: 8px 6px; border-bottom: 1px solid #e4e7eb; }
.todo-item input[type='checkbox'] { width: 16px; height: 16px; cursor: pointer; }
.todo-item span { flex: 1; font-size: 15px; }
.todo-item.done span { text-decoration: line-through; color: #7b8794; }
.delete-btn { padding: 4px 8px; font-size: 12px; border: none; border-radius: 6px; background: #fee2e2; color: #b91c1c; cursor: pointer; }
.delete-btn:hover { background: #fecaca; }
#counter { font-size: 13px; color: #52606d; margin: 0; }",
  "scripts": [
    "const render = () => {
  const list = root.querySelector('#todo-list');
  list.replaceChildren();
  state.todos.forEach((todo, i) => {
    const li = root.create('li');
    li.classList.add('todo-item');
    if (todo.done) {
      li.classList.add('done');
    }
    const checkbox = root.create('input');
    checkbox.setAttribute('type', 'checkbox');
    checkbox.checked = todo.done;
    checkbox.addEventListener('change', () => {
      todo.done = checkbox.checked;
      render();
    });
    const span = root.create('span');
    span.textContent = todo.text;
    const del = root.create('button');
    del.textContent = 'Delete';
    del.classList.add('delete-btn');
    del.addEventListener('click', () => {
      state.todos.splice(i, 1);
      render();
    });
    li.append(checkbox);
    li.append(span);
    li.append(del);
    list.append(li);
  });
  const left = state.todos.filter((t) => !t.done).length;
  root.querySelector('#counter').textContent = left + (left === 1 ? ' item left' : ' items left');
};
if (!state.todos) {
  state.todos = [
    { text: 'Book train tickets', done: false },
    { text: 'Reserve a hotel room', done: false },
    { text: 'Make a list of restaurants to try', done: true }
  ];
}
render();
const addBtn = root.querySelector('#add-btn');
const input = root.querySelector('#new-todo');
const addTodo = () => {
  const text = input.value.trim();
  if (text) {
    state.todos.push({ text: text, done: false });
    input.value = '';
    render();
  }
};
addBtn.addEventListener('click', addTodo);"
  ]
}
